def kebab_to_camel(s):
    parts = s.split('-')
    if not parts:
        return s
    result = parts[0]
    for p in parts[1:]:
        if p:
            result += p[0].upper() + p[1:]
    return result

def camel_to_kebab(s):
    result = []
    for i, ch in enumerate(s):
        if ch.isupper() and i > 0:
            result.append('-')
        result.append(ch.lower())
    return ''.join(result)

def spaced_to_pascal(s):
    words = s.split()
    return ''.join(w[0].upper() + w[1:] for w in words)

def constant_case(s):
    words = re.split(r'[ \-_]+', s)
    words = [w for w in words if w]
    return '_'.join(w.upper() for w in words)

def format_currency(amount):
    sign = '-' if amount < 0 else ''
    return f"{sign}${abs(amount):,.2f}"

def ordinal_suffix(n):
    a = abs(n)
    last_two = a % 100
    last_one = a % 10
    if 11 <= last_two <= 13:
        suf = 'th'
    elif last_one == 1:
        suf = 'st'
    elif last_one == 2:
        suf = 'nd'
    elif last_one == 3:
        suf = 'rd'
    else:
        suf = 'th'
    return f"{n}{suf}"

def format_signed_number(n):
    if n > 0:
        return f"+{n}"
    elif n < 0:
        return str(n)
    else:
        return "0"

def format_fraction(numerator, denominator):
    g = math.gcd(numerator, denominator)
    return f"{numerator // g}/{denominator // g}"

def roman_numeral(n):
    vals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
    ]
    result = []
    for v, sym in vals:
        while n >= v:
            result.append(sym)
            n -= v
    return ''.join(result)

def format_credit_card_mask(number):
    n = len(number)
    masked = '*' * (n - 4) + number[-4:] if n > 4 else number
    groups = []
    for i in range(0, len(masked), 4):
        groups.append(masked[i:i + 4])
    return ' '.join(groups)

def pluralize(word):
    if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
        return word + 'es'
    if len(word) >= 2 and word[-1] == 'y' and word[-2].lower() not in 'aeiou':
        return word[:-1] + 'ies'
    return word + 's'

def pluralize_count(word, n):
    if n == 1:
        return f"1 {word}"
    if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
        p = word + 'es'
    elif len(word) >= 2 and word[-1] == 'y' and word[-2].lower() not in 'aeiou':
        p = word[:-1] + 'ies'
    else:
        p = word + 's'
    return f"{n} {p}"

def singularize(word):
    if word.endswith('ies') and len(word) > 3:
        return word[:-3] + 'y'
    if word.endswith(('ses', 'xes', 'zes', 'ches', 'shes')):
        return word[:-2]
    if word.endswith('s') and not word.endswith('ss'):
        return word[:-1]
    return word

def format_count_noun(n, singular, plural):
